package com.ravikisan.platform.compose.core.logic

import kotlinx.serialization.json.jsonObject
import org.junit.Assert.assertEquals
import org.junit.Test

/**
 * Golden-vector tests for [sm2]/[buildCards]/[dueQueue]/[normalizeStore] —
 * expectations generated by executing the REAL website TypeScript
 * (frontend/features/srs) via android-native/golden/generate-golden.ts.
 * Parity plan §0.5 task 1: "same code, different language".
 */
class SrsGoldenTest {

    private val golden = Golden.obj("srs-golden.json")

    private fun state(o: kotlinx.serialization.json.JsonObject) = SrsState(
        ease = o.double("ease"),
        interval = o.int("interval"),
        reps = o.int("reps"),
        lapses = o.int("lapses"),
        due = o.str("due"),
    )

    private fun card(o: kotlinx.serialization.json.JsonObject) = SrsCard(
        id = o.str("id"),
        subjectKey = o.str("subjectKey"),
        kind = o.str("kind"),
        front = o.str("front"),
        back = o.str("back"),
    )

    @Test
    fun `sm2 matches the TS scheduler on every golden case`() {
        for (c in golden.arr("sm2")) {
            val o = c.jsonObject
            val prev = (o["prev"] as? kotlinx.serialization.json.JsonObject)?.let { state(it) }
            val expected = state(o.obj("expected"))
            assertEquals("case ${o.str("name")}", expected, sm2(prev, o.int("quality"), o.str("today")))
        }
    }

    @Test
    fun `addDays matches the TS calendar arithmetic`() {
        for (c in golden.arr("addDays")) {
            val o = c.jsonObject
            assertEquals("case ${o.str("iso")}+${o.int("days")}", o.str("expected"), addDays(o.str("iso"), o.int("days")))
        }
    }

    @Test
    fun `buildCards matches the TS deck builder incl dedupe and trims`() {
        val bc = golden.obj("buildCards")
        val bank = bc.obj("bank").toBank()
        val expected = bc.arr("expected").map { card(it.jsonObject) }
        assertEquals(expected, buildCards(bc.str("subjectKey"), bank))
    }

    @Test
    fun `dueQueue matches the TS queue on the golden store`() {
        val dq = golden.obj("dueQueue")
        val cards = golden.obj("buildCards").arr("expected").map { card(it.jsonObject) }
        val store = buildStore()
        val expected = dq.obj("expected")
        val actual = dueQueue(cards, store, dq.str("today"), dq.int("newLimit"))
        assertEquals(expected.arr("due").map { card(it.jsonObject) }, actual.due)
        assertEquals(expected.arr("fresh").map { card(it.jsonObject) }, actual.fresh)
    }

    private fun buildStore(): Map<String, SrsState> {
        val normalized = normalizeStore(Golden.obj("srs-golden.json").obj("store").obj("junk").toString())
        val added = golden.obj("store").arr("added").associate {
            it.jsonObject.str("id") to state(it.jsonObject.obj("state"))
        }
        return normalized + added
    }

    @Test
    fun `normalizeStore drops every invalid entry exactly like the TS`() {
        val ns = golden.obj("normalizeStore")
        val expected = ns.obj("expected").mapValues { state(it.value.jsonObject) }
        assertEquals(expected, normalizeStore(ns.obj("input").toString()))
    }
}
